const authError = (code, detail) => ({
    statusCode: 401,
    headers: { 'Content-Type': 'application/json', 'WWW-Authenticate': 'Bearer error="' + code + '"' },
    payload: { detail }
});

const mode = String(env.get('AI_INSIGHT_AUTH__MODE') || 'verified').toLowerCase();
if (mode === 'off') {
    // The header-trust mode is REMOVED from the code. A deployment
    // still asking for it fails closed instead of trusting client headers.
    Object.assign(msg, authError('mode_removed', 'the off header-trust mode was removed: verified tokens only'));
    msg.identity = null;
    msg.authRejected = true;
    node.warn('ai-insight-auth: the off mode is not supported anymore — failing closed');
    return [null, null, msg];
}

// The correlation id rides the request (or is minted),
// is echoed back on the response, and every decision is logged as a structured
// JSON event — verdicts only, NEVER the token or any VC/VP content.
const reqHeaders = (msg.req && msg.req.headers) || {};
msg._authCorrelationId = reqHeaders['x-correlation-id'] || msg._msgid || (Date.now() + '-' + Math.random().toString(36).slice(2));
if (msg.res && typeof msg.res.set === 'function') msg.res.set('X-Correlation-Id', msg._authCorrelationId);
const emitAuthEvent = () => {
    node.warn(JSON.stringify({
        event: 'ai_insight.auth',
        correlationId: msg._authCorrelationId || null,
        at: new Date().toISOString(),
        result: msg.authRejected ? 'denied' : 'allowed',
        code: (msg.payload && msg.payload.detail) || null,
        sub: (msg.identity && msg.identity.sub) || null,
        roles: (msg.identity && msg.identity.roles) || []
    }));
};
const authHeader = (msg.req && msg.req.headers && msg.req.headers.authorization) || '';
const m = /^Bearer\s+(.+)$/i.exec(authHeader.trim());
if (!m) {
    Object.assign(msg, authError('missing_authorization', 'Authorization: Bearer <access token> is required'));
    msg.identity = null;
    msg.authRejected = true;
    emitAuthEvent();
    return [null, null, msg];
}
const token = m[1];

let header;
let payload;
try {
    const parts = token.split('.');
    if (parts.length !== 3) throw new Error('not a JWS');
    header = JSON.parse(Buffer.from(parts[0], 'base64url').toString('utf8'));
    payload = JSON.parse(Buffer.from(parts[1], 'base64url').toString('utf8'));
} catch (e) {
    Object.assign(msg, authError('invalid_token', 'malformed bearer token'));
    msg.identity = null;
    msg.authRejected = true;
    emitAuthEvent();
    return [null, null, msg];
}

// The token issuer and its JWKS are required settings: the guard by default
// deployment, Keycloak or any other issuer when set explicitly. Without them
// every call fails closed (503), naming the missing setting.
const issuer = env.get('AI_INSIGHT_AUTH__ISSUER') || '';
const jwksUrl = env.get('AI_INSIGHT_AUTH__JWKS_URL') || '';
if (!issuer || !jwksUrl) {
    msg.statusCode = 503;
    msg.headers = { 'Content-Type': 'application/json' };
    msg.payload = { detail: 'authentication not configured: set AI_INSIGHT_AUTH__ISSUER and AI_INSIGHT_AUTH__JWKS_URL' };
    msg.identity = null;
    msg.authRejected = true;
    emitAuthEvent();
    return [null, null, msg];
}
if (payload.iss !== issuer) {
    Object.assign(msg, authError('invalid_token', 'unexpected token issuer'));
    msg.identity = null;
    msg.authRejected = true;
    emitAuthEvent();
    return [null, null, msg];
}

msg._authToken = token;
msg._authKid = header.kid || null;
msg._authIssuer = issuer;
msg._authOrigPayload = msg.payload;

const ttlMs = Math.max(60, Number(env.get('AI_INSIGHT_AUTH__JWKS_TTL_SECONDS') || 300)) * 1000;
const cache = global.get('aiInsightAuthJwksCache');
const kidInCache = cache && Array.isArray(cache.keys)
    && (!msg._authKid || cache.keys.some((k) => k.kid === msg._authKid));
if (cache && (Date.now() - cache.fetchedAt) < ttlMs && kidInCache) {
    msg._authJwks = { keys: cache.keys };
    return [msg, null, null];
}

msg.url = jwksUrl;
msg._authJwksFetched = true;
return [null, msg, null];

// jose is in scope from this node's own libs declaration
// (functionExternalModules injects it as a bound variable).
(async () => {
    const authError = (code, detail) => ({
        statusCode: 401,
        headers: { 'Content-Type': 'application/json', 'WWW-Authenticate': 'Bearer error="' + code + '"' },
        payload: { detail }
    });
    try {
        let jwksDoc;
        if (msg._authJwksFetched) {
            const status = Number(msg.statusCode || 0);
            jwksDoc = msg.payload;
            if (status !== 200 || !jwksDoc || !Array.isArray(jwksDoc.keys)) {
                msg.statusCode = 503;
                msg.headers = { 'Content-Type': 'application/json' };
                msg.payload = { detail: 'Authorization server unavailable (JWKS fetch failed)' };
                msg.identity = null;
                msg.authRejected = true;
                node.send(msg);
                return;
            }
            global.set('aiInsightAuthJwksCache', { keys: jwksDoc.keys, fetchedAt: Date.now() });
        } else {
            jwksDoc = msg._authJwks;
        }

        msg.payload = msg._authOrigPayload;

        const kid = msg._authKid;
        const jwk = jwksDoc.keys.find((k) => !kid || k.kid === kid);
        if (!jwk) {
            Object.assign(msg, authError('invalid_token', 'unknown signing key'));
            msg.identity = null;
            msg.authRejected = true;
            node.send(msg);
            return;
        }

        const key = await jose.importJWK(jwk, jwk.alg || 'RS256');
        const opts = { issuer: msg._authIssuer, clockTolerance: 5 };
        const audience = env.get('AI_INSIGHT_AUTH__AUDIENCE');
        if (audience) opts.audience = audience;

        const verified = await jose.jwtVerify(msg._authToken, key, opts);
        const claims = verified.payload;
        // Roles claim: a dot path into the verified claims. The default,
        // roles, is where the guard's tokens carry them; for a Keycloak issuer
        // set AI_INSIGHT_AUTH__ROLES_CLAIM=realm_access.roles.
        const rolesPath = String(env.get('AI_INSIGHT_AUTH__ROLES_CLAIM') || 'roles').split('.');
        const rolesValue = rolesPath.reduce((o, k) => (o && typeof o === 'object' ? o[k] : undefined), claims);
        const roles = Array.isArray(rolesValue) ? rolesValue.filter((r) => typeof r === 'string') : [];
        msg.identity = {
            sub: claims.sub || null,
            username: claims.preferred_username || null,
            client: claims.azp || null,
            roles,
            verifiedAt: new Date().toISOString()
        };
        msg.authRejected = false;
        delete msg.statusCode;
    } catch (e) {
        if (e && e.code === 'ERR_JWT_EXPIRED') {
            Object.assign(msg, authError('token_expired', 'access token expired'));
        } else if (e && e.code === 'ERR_JWT_CLAIM_VALIDATION_FAILED') {
            Object.assign(msg, authError('invalid_token', 'token claim validation failed: ' + (e.claim || 'unknown')));
        } else {
            Object.assign(msg, authError('invalid_token', 'token signature verification failed'));
        }
        msg.identity = null;
        msg.authRejected = true;
    }
    // Decision event with the correlation id (same shape as the DSP
    // iam.verify event) — verdicts only, no credential material.
    node.warn(JSON.stringify({
        event: 'ai_insight.auth',
        correlationId: msg._authCorrelationId || null,
        at: new Date().toISOString(),
        result: msg.authRejected ? 'denied' : 'allowed',
        code: (msg.payload && msg.payload.detail) || null,
        sub: (msg.identity && msg.identity.sub) || null,
        roles: (msg.identity && msg.identity.roles) || []
    }));
    delete msg._authCorrelationId;
    delete msg._authToken;
    delete msg._authKid;
    delete msg._authIssuer;
    delete msg._authJwks;
    delete msg._authJwksFetched;
    delete msg._authOrigPayload;
    node.send(msg);
    node.done();
})();
return;
